mapper.select:
SELECT s.id AS id, s.student_id AS studentId, s.student_name AS studentName, sc.status_name AS statusName, CASE WHEN s.entry_han_date IS NULL THEN s.entry_book_date WHEN s.entry_book_date IS NULL THEN s.entry_han_date WHEN s.entry_han_date <= s.entry_book_date THEN s.entry_han_date ELSE s.entry_book_date END AS entryDate, g.grade_name AS gradeName, s.school AS school, c.center_name AS centerName,
STUFF(( SELECT DISTINCT ', ' + cc.class_name FROM erp_time_table_assign ta JOIN erp_time_table t ON t.time_table_key = ta.time_table_key JOIN erp_class_code cc ON cc.class_key = t.class_key WHERE ta.student_id = s.student_id AND cc.class_type = 1
AND t.user_code = #{userCode}
FOR XML PATH(''), TYPE ).value('.', 'nvarchar(max)'), 1, 2, '') AS hanClass,
STUFF(( SELECT DISTINCT ', ' + cc.class_name FROM erp_time_table_assign ta JOIN erp_time_table t ON t.time_table_key = ta.time_table_key JOIN erp_class_code cc ON cc.class_key = t.class_key WHERE ta.student_id = s.student_id AND cc.class_type = 2
AND t.user_code = #{userCode}
FOR XML PATH(''), TYPE ).value('.', 'nvarchar(max)'), 1, 2, '') AS bookClass
FROM ERP_STUDENT s JOIN ERP_status_code sc ON sc.status_key = s.status_key JOIN ERP_grade_code g ON g.grade_key = s.grade_key JOIN ERP_center c ON c.center_code = s.center_code
t.time_table_code = #{timeTableCode}
ORDER BY s.id

mapper.insert:
INSERT INTO status_history
    (student_no, status_no, reason, updated_at)
values (#{studentNo}, #{statusNo}, #{reason}, CURRENT_TIMESTAMP);

mapper.update:
UPDATE student_tb
SET status_no = #{statusNo}
WHERE student_no = #{studentNo};

mapper.select:
SELECT s.student_id AS studentId, sth.TRANSFER_NO as historyNo, sth.MOVE_AT as moveAt, s.STUDENT_NAME as studentName, c.CLASS_NAME as className, u1.USERNAME as fromTeacher, u2.USERNAME as toTeacher, sth.TRANSFER_REASON as transferReason, sth.CREATED_AT as createdAt
FROM STUDENT_TRANSFER_HISTORY sth JOIN class_code c ON sth.class_no = c.class_no JOIN user_tb u1 ON sth.from_user_no = u1.user_no JOIN user_tb u2 ON sth.to_user_no = u2.user_no JOIN student_tb s ON sth.student_no = s.student_no JOIN grade_code g ON s.grade_no = g.grade_no
s.student_no = #{studentId}

SELECT COUNT(1) > 0
FROM student_monthly_snapshot
WHERE snapshot_ym = #{ym}

mapper.insert:
DELETE FROM student_monthly_snapshot WHERE snapshot_ym = #{ym};
INSERT INTO student_monthly_snapshot (snapshot_ym, active_count, rest_count, withdrawn_count, wait_count, created_at)
SELECT #{ym}, SUM(CASE WHEN sc.status = '재원중' THEN 1 ELSE 0 END), SUM(CASE WHEN sc.status = '휴원' THEN 1 ELSE 0 END), SUM(CASE WHEN sc.status = '탈퇴' THEN 1 ELSE 0 END), SUM(CASE WHEN sc.status = '입학취소' THEN 1 ELSE 0 END), CURRENT_TIMESTAMP
FROM student_tb s JOIN status_code sc ON s.status_no = sc.status_no;
